// Generated by tools/analyze_menu_actions.py. Screens come from
// the action dispatcher at 0x50f7d0 and RTTI constructor names;
// menu labels are not used as evidence.
enum class MenuActionKind : u8 {
    None, Screen, ContinueGame, ResumeGame, ExitStage, ExitGame,
    ManagerPhase, Cutscene, CharacterSelected,
};

struct RecoveredMenuAction {
    u32 actionCode;
    MenuActionKind kind;
    u8 screenCount;
    u8 variantCount;
    FlowScreen screens[2];
    u32 variantSuppliers[2];
    const char* cutscenePath;
    const char* note;
    const char* conditionalCutscenes[2];
    u8 conditionalCutsceneCount;
};

