inline constexpr std::size_t kRecoveredMenuActionsCount =
    sizeof(kRecoveredMenuActions) / sizeof(kRecoveredMenuActions[0]);

inline const RecoveredMenuAction* findMenuAction(u32 actionCode) {
    for (const RecoveredMenuAction& action : kRecoveredMenuActions)
        if (action.actionCode == actionCode) return &action;
    return nullptr;
}

inline bool menuActionHasScreen(u32 actionCode) {
    const RecoveredMenuAction* action = findMenuAction(actionCode);
    return action && action->kind == MenuActionKind::Screen &&
           action->screenCount != 0;
}

inline FlowScreen menuActionScreen(u32 actionCode, u8 index = 0) {
    const RecoveredMenuAction* action = findMenuAction(actionCode);
    if (!action || action->kind != MenuActionKind::Screen ||
        index >= action->screenCount)
        return FlowScreen::TitleMenu;
    return action->screens[index];
}

inline u32 menuActionSupplier(u32 actionCode, u8 index = 0) {
    const RecoveredMenuAction* action = findMenuAction(actionCode);
    if (!action || index >= action->variantCount) return 0;
    return action->variantSuppliers[index];
}

inline const char* menuActionCutscene(u32 actionCode) {
    const RecoveredMenuAction* action = findMenuAction(actionCode);
    return action ? action->cutscenePath : "";
}

inline const char* menuActionConditionalCutscene(u32 actionCode,
                                                   u8 index = 0) {
    const RecoveredMenuAction* action = findMenuAction(actionCode);
    if (!action || index >= action->conditionalCutsceneCount) return "";
    return action->conditionalCutscenes[index];
}

inline const char* menuActionKindName(MenuActionKind kind) {
    switch (kind) {
    case MenuActionKind::None: return "None";
    case MenuActionKind::Screen: return "Screen";
    case MenuActionKind::ContinueGame: return "ContinueGame";
    case MenuActionKind::ResumeGame: return "ResumeGame";
    case MenuActionKind::ExitStage: return "ExitStage";
    case MenuActionKind::ExitGame: return "ExitGame";
    case MenuActionKind::ManagerPhase: return "ManagerPhase";
    case MenuActionKind::Cutscene: return "Cutscene";
    case MenuActionKind::CharacterSelected: return "CharacterSelected";
    }
    return "None";
}

